public class DefaultBoxAndWhiskerCategoryDataset_add_TriageGen1Test {

    private DefaultBoxAndWhiskerCategoryDataset dataset;

    @Before
    public void setUp() {
        dataset = new DefaultBoxAndWhiskerCategoryDataset();
    }

    @Test
    public void testAddFirstItemSetsBounds() {
        // Create item with specific outliers
        BoxAndWhiskerItem item = new BoxAndWhiskerItem(null, null, null, null, null, null, 10.0, 20.0);
        // Note: Based on the code logic, it uses item.getMinOutlier() and item.getMaxOutlier()
        // We need a way to mock or create BoxAndWhiskerItem with specific outliers.
        // Assuming BoxAndWhiskerItem constructor or setters allow setting outliers.

        // Since I cannot see BoxAndWhiskerItem implementation, I will assume standard usage 
        // where we can pass values for min/max outliers.
        BoxAndWhiskerItem item1 = createItem(5.0, 15.0);

        dataset.add(item1, "Row1", "Col1");

        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(15.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddItemUpdatesMax() {
        dataset.add(createItem(5.0, 15.0), "R1", "C1");
        dataset.add(createItem(2.0, 25.0), "R2", "C2");

        assertEquals(2.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(25.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddItemUpdatesMin() {
        dataset.add(createItem(5.0, 15.0), "R1", "C1");
        dataset.add(createItem(1.0, 10.0), "R2", "C2");

        assertEquals(1.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(15.0, dataset.getRangeUpperBound(true), 0.001);
    }

    @Test
    public void testAddWithNullOutliers() {
        // Test the Double.isNaN logic when outliers are null
        BoxAndWhiskerItem item = createItem(null, null);
        dataset.add(item, "R1", "C1");

        // maxval and minval become NaN, so they shouldn't update the existing NaN bounds 
        // in a way that breaks the logic, but the code sets maximumRangeValue = maxval (NaN)
        // if it is currently NaN.
        assertEquals(Double.NaN, dataset.getRangeLowerBound(true), 0.0);
        assertEquals(Double.NaN, dataset.getRangeUpperBound(true), 0.0);
    }

    @Test
    public void testUpdateBoundsBranch() {
        // To trigger (this.maximumRangeValueRow == r && this.maximumRangeValueColumn == c)
        // We add an item to the same position as the current maximum
        dataset.add(createItem(10.0, 50.0), "R1", "C1");

        // Adding another item to the same R1, C1 should trigger the 'if' block for updateBounds()
        // Since updateBounds() is internal, we verify it doesn't crash and maintains state.
        dataset.add(createItem(5.0, 60.0), "R1", "C1");

        // If updateBounds is called, it recalculates based on all data.
        // However, the logic in the provided snippet is specific to the current item.
        // We check if the dataset still functions.
        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001); 
    }

    @Test
    public void testAddSamePositionDoesNotUpdateMaxViaElse() {
        // Adding to a different position to ensure the 'else' block is taken
        dataset.add(createItem(10.0, 50.0), "R1", "C1");
        dataset.add(createItem(5.0, 40.0), "R2", "C2"); // Different position

        assertEquals(5.0, dataset.getRangeLowerBound(true), 0.001);
        assertEquals(50.0, dataset.getRangeUpperBound(true), 0.001);
    }

    /**
     * Helper to create BoxAndWhiskerItem. 
     * Since the exact constructor for BoxAndWhiskerItem is not provided, 
     * this assumes a constructor or a way to set outliers.
     */
    private BoxAndWhiskerItem createItem(Double minOutlier, Double maxOutlier) {
        // This is a mock-like implementation. In a real scenario, use actual constructor.
        // Given the context, we assume the class exists and can be instantiated.
        return new BoxAndWhiskerItem(
            null, null, null, null, null, null, 
            minOutlier, maxOutlier
        );
    }
}

